SELECT

FROM order_history_example a WHERE 1 = 1

    AND a.create_time = #{createTime}


    AND a.finish_time = #{finishTime}


    AND a.user_id = #{userId}


    AND a.market = #{market}


    AND a.source = #{source}


    AND a.t = #{t}


    AND a.side = #{side}


    AND a.price = #{price}


    AND a.amount = #{amount}


    AND a.taker_fee = #{takerFee}


    AND a.maker_fee = #{makerFee}


    AND a.deal_stock = #{dealStock}


    AND a.deal_money = #{dealMoney}


    AND a.deal_fee = #{dealFee}

limit 1

SELECT

FROM order_history_example a WHERE 1 = 1

    AND a.create_time = #{createTime}


    AND a.finish_time = #{finishTime}


    AND a.user_id = #{userId}


    AND a.market LIKE CONCAT('%',#{market}, '%')


    AND a.source LIKE CONCAT('%',#{source}, '%')


    AND a.t = #{t}


    AND a.side = #{side}


    AND a.price = #{price}


    AND a.amount = #{amount}


    AND a.taker_fee = #{takerFee}


    AND a.maker_fee = #{makerFee}


    AND a.deal_stock = #{dealStock}


    AND a.deal_money = #{dealMoney}


    AND a.deal_fee = #{dealFee}
